{"function": "() => {
  const metadata = {};

  // Video title
  metadata.title = document.title.replace(' - YouTube', '').trim();

  // Channel info
  const channelLink = document.querySelector('ytd-video-owner-renderer #channel-name a');
  metadata.channelName = channelLink?.innerText?.trim();
  metadata.channelUrl = channelLink?.href;

  // View count and upload date from info line
  const infoLine = document.querySelector('#info-container span:nth-child(3)') ||
                   document.querySelector('#info span');
  if (infoLine) {
    const text = infoLine.innerText;
    // parse view count and upload date
    metadata.infoLine = text;
  }

  // More precise view count
  const viewCountElem = document.querySelector('span.view-count');
  metadata.viewCount = viewCountElem?.innerText?.trim();

  // Upload date relative
  const uploadDateElem = document.querySelector('span.date');
  metadata.uploadDate = uploadDateElem?.innerText?.trim();

  // Likes
  const likeButton = document.querySelector('ytd-toggle-button-renderer[aria-label*="like"]');
  metadata.likes = likeButton?.getAttribute('aria-label')?.replace('like this video', '').trim();

  // Description
  const descContainer = document.querySelector('ytd-video-description-renderer');
  if (descContainer) {
    // Check if there's a "more" button and click
    const moreButton = descContainer.querySelector('#more') ||
                      descContainer.querySelector('#expand');
    if (moreButton) moreButton.click();
    metadata.description = descContainer.innerText;
  }

  // Comments - get all comment threads
  const comments = [];
  const commentThreads = document.querySelectorAll('ytd-comment-thread-renderer');
  commentThreads.forEach(thread => {
    const author = thread.querySelector('#author-text')?.innerText?.trim();
    const text = thread.querySelector('#content-text')?.innerText?.trim();
    const likes = thread.querySelector('#vote-count-middle')?.innerText?.trim();
    const time = thread.querySelector('yt-formatted-string.published-time-text')?.innerText?.trim();
    const replies = thread.querySelector('#reply-count')?.innerText?.trim();
    comments.push({ author, text, likes, time, replies });
  });
  metadata.comments = comments;
  metadata.commentCount = commentThreads.length;

  // Video duration
  const durationElem = document.querySelector('.ytp-time-duration');
  metadata.duration = durationElem?.innerText?.trim();

  // Video URL
  metadata.videoUrl = window.location.href;
  metadata.videoId = new URL(window.location.href).searchParams.get('v');

  return metadata;
}"}

